import {jest} from '@jest/globals';
import net from 'node:net';
import {setLogger} from '../shared/logger.js';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import type {ExtWebSocket} from './ws/connectionHandler.js';
import type {ChatSession} from '../types/session.js';
import type {SessionStore} from '../types/sessionStore.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
import type {WsAuthenticator} from '../types/auth.js';

// The defect this pins is an omission: both hooks are declared on HalServerOptions, and one was never forwarded.

const settle = () => new Promise<void>(resolve => setTimeout(resolve, 0));

const harness = (onConnect?: (session: ChatSession) => void) => {
  const sessionStore = {
    create: (sessionId: string, userId: string | number): ChatSession => ({sessionId, userId, entries: []}),
    delete: () => true,
  } as unknown as SessionStore;

  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: jest.fn() as unknown as WsAuthenticator,
    sessionStore,
    orchestrator: {} as ChatOrchestrator,
    onConnect,
  });

  const ws = {
    userId: 'u1',
    isAlive: true,
    send: () => undefined,
    on: () => undefined,
    // The handler pauses the socket across an awaited create and resumes once its listeners are attached.
    pause: () => undefined,
    resume: () => undefined,
    close: () => undefined,
  } as unknown as ExtWebSocket;

  return {hal, ws};
};

describe('createServer hook wiring', () => {
  it('forwards onConnect to the connection handler', async () => {
    const seen: ChatSession[] = [];
    const {hal, ws} = harness(session => void seen.push(session));

    hal.wss.emit('connection', ws);
    await settle();
    hal.wss.emit('close');

    expect(seen.length).toBe(1);
  });

  it('accepts a server configured without either hook', async () => {
    const {hal, ws} = harness();

    hal.wss.emit('connection', ws);
    await settle();
    hal.wss.emit('close');

    expect(hal.wss.listenerCount('connection')).toBe(1);
  });
});

// An EventEmitter with no `error` listener throws, so a socket error on a running server ended the process.
describe('a server error after start', () => {
  const engineLines: string[] = [];

  beforeEach(() => {
    engineLines.length = 0;
    const collect = (_category: string, message: string) => void engineLines.push(message);
    setLogger({debug: collect, info: collect, warn: collect, error: collect});
  });

  afterEach(() => {
    setLogger();
  });

  const started = async () => {
    const {hal} = harness();
    await hal.start(0);
    return hal;
  };

  // A stopped engine and a port something else holds, so the next start is refused by the OS.
  const refusedStart = async () => {
    const hal = await started();
    await hal.stop();
    const blocker = net.createServer();
    await new Promise<void>(resolve => blocker.listen(0, resolve));
    const taken = (blocker.address() as net.AddressInfo).port;
    const release = () => new Promise<void>(resolve => blocker.close(() => resolve()));
    return {hal, taken, release};
  };

  it('is reported rather than ending the process', async () => {
    const hal = await started();

    hal.server.emit('error', new Error('late failure'));
    await hal.stop();

    expect(engineLines).toContain('server error after start');
  });

  it('leaves exactly one listener behind, however many times the server is restarted', async () => {
    const hal = await started();
    await hal.stop();
    await hal.start(0);

    const count = hal.server.listenerCount('error');
    await hal.stop();

    expect(count).toBe(1);
  });

  it('is still reported after stop, because an error with no handler ends the process', async () => {
    const hal = await started();
    await hal.stop();

    hal.server.emit('error', new Error('after stop'));

    expect(engineLines).toContain('server error after start');
  });

  it('is not reported for a start that was cleanly refused, because nothing was running', async () => {
    const {hal, taken, release} = await refusedStart();

    await hal.start(taken).catch((error: NodeJS.ErrnoException) => engineLines.push(`rejected ${error.code}`));
    await release();

    expect(engineLines).toEqual(['HAL Engine started', 'rejected EADDRINUSE']);
  });

  it('stops cleanly after a refused start, so a finally block does not turn one failure into two', async () => {
    const {hal, taken, release} = await refusedStart();
    await hal.start(taken).catch(() => undefined);

    const stopped = hal.stop().then(
      () => 'resolved',
      (error: NodeJS.ErrnoException) => `rejected ${error.code}`
    );
    await release();

    await expect(stopped).resolves.toBe('resolved');
  });

  it('refuses a second start without stripping the running server of its handler', async () => {
    const hal = await started();

    await hal.start(0).catch((error: Error) => engineLines.push(`rejected ${error.message}`));
    hal.server.emit('error', new Error('after the refused start'));
    await hal.stop();

    expect(engineLines).toEqual([
      'HAL Engine started',
      'rejected HAL Engine is already started',
      'server error after start',
    ]);
  });
});
import {once} from 'node:events';
import type {IncomingMessage} from 'node:http';
import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import {HAL_WS_SUBPROTOCOL, credentialFromSubprotocol} from './ws/subprotocol.js';
import type {WsAuthenticator} from '../types/auth.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import {setLogger} from '../shared/logger.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';

// Real upgrades over a real socket: what the 101 carries is the contract, and no double can observe it.

const TOKEN = 'super-secret-token';

interface Handshake {
  answered: string | undefined;
  leakedHeaders: string[];
  socketProtocol: string;
  authorization: string | undefined;
}

const signal = () => {
  let release = (): void => undefined;
  const fired = new Promise<void>(resolve => {
    release = resolve;
  });
  return {fired, release: () => release()};
};

const admitEveryone: WsAuthenticator = async () => ({id: 'u1'});

const engine = async (wsAuth: WsAuthenticator = admitEveryone) => {
  // Read at connect: the close handler clears authHeaders, so a post-close read would see nothing.
  const bearers: Array<string | undefined> = [];
  const serverSockets: WebSocket[] = [];
  const disconnected = signal();
  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth,
    sessionStore: new InMemorySessionStore(),
    orchestrator: {} as ChatOrchestrator,
    onConnect: session => void bearers.push(session.authHeaders?.authorization),
    onDisconnect: disconnected.release,
  });
  hal.wss.on('connection', socket => void serverSockets.push(socket));
  await hal.start(0);
  const {port} = hal.server.address() as AddressInfo;
  return {hal, bearers, serverSockets, disconnected, url: `ws://127.0.0.1:${port}/hal/ws/c1`};
};

// Connect, ping, close: the whole lifecycle a credential could be logged in.
const roundTrip = async (url: string, offer: string[], headers: Record<string, string>) => {
  const client = new WebSocket(url, offer, {headers});
  // Both listened for before either is awaited: the connected frame can land in the same tick as the 101.
  const upgraded = once(client, 'upgrade');
  const connected = once(client, 'message');
  const [response] = (await upgraded) as [IncomingMessage];
  await connected;
  client.send(JSON.stringify({type: 'ping', timestamp: 1}));
  await once(client, 'message');
  client.close();
  return response;
};

const handshake = async (offer: string[], headers: Record<string, string> = {}): Promise<Handshake> => {
  const {hal, bearers, serverSockets, disconnected, url} = await engine();
  const response = await roundTrip(url, offer, headers);
  await disconnected.fired;
  await hal.stop();

  const [bearer] = bearers;
  const [serverSocket] = serverSockets;
  const {rawHeaders} = response;
  return {
    answered: response.headers['sec-websocket-protocol'],
    leakedHeaders: rawHeaders.filter(value => value.includes(TOKEN)),
    socketProtocol: serverSocket.protocol,
    authorization: bearer,
  };
};

// Raced against open, so a server that still accepts an offer fails the test instead of hanging it.
const clientOutcome = (client: WebSocket): Promise<string> =>
  Promise.race([
    once(client, 'error').then(([error]) => (error as Error).message),
    once(client, 'open').then(() => 'opened'),
  ]);

// The authenticator the docs recommend: it reads the credential the way the engine does.
const readsSubprotocol: WsAuthenticator = async request =>
  credentialFromSubprotocol(request.headers['sec-websocket-protocol']) ? {id: 'u1'} : null;

// An offer without the marker is answered with no subprotocol, which the ws client fails after the 101.
const refusedHandshake = async (offer: string[]) => {
  const {hal, disconnected, url} = await engine();
  const client = new WebSocket(url, offer);
  const upgraded = once(client, 'upgrade');
  const outcome = clientOutcome(client);
  const [response] = (await upgraded) as [IncomingMessage];
  const clientError = await outcome;
  client.close();
  await disconnected.fired;
  await hal.stop();
  return {
    answered: response.headers['sec-websocket-protocol'],
    leakedHeaders: response.rawHeaders.filter(value => value.includes(TOKEN)),
    clientError,
  };
};

describe('the WebSocket handshake', () => {
  const lines: string[] = [];

  beforeEach(() => {
    lines.length = 0;
    const collect = (category: string, message: string, fields?: Record<string, unknown>) =>
      void lines.push(JSON.stringify({category, message, fields}));
    setLogger({debug: collect, info: collect, warn: collect, error: collect});
  });

  afterEach(() => {
    setLogger();
  });

  it('answers a hal.v1 and token offer with hal.v1 alone, and forwards the token as a bearer', async () => {
    expect(await handshake([HAL_WS_SUBPROTOCOL, TOKEN])).toEqual({
      answered: HAL_WS_SUBPROTOCOL,
      leakedHeaders: [],
      socketProtocol: HAL_WS_SUBPROTOCOL,
      authorization: `Bearer ${TOKEN}`,
    });
  });

  it('connects a client offering only the marker, reading its credential from the Authorization header', async () => {
    expect(await handshake([HAL_WS_SUBPROTOCOL], {Authorization: 'Bearer from-header'})).toEqual({
      answered: HAL_WS_SUBPROTOCOL,
      leakedHeaders: [],
      socketProtocol: HAL_WS_SUBPROTOCOL,
      authorization: 'Bearer from-header',
    });
  });

  it('answers a bare-token offer with no subprotocol, so the client fails it and no response header holds the token', async () => {
    expect(await refusedHandshake([TOKEN])).toEqual({
      answered: undefined,
      leakedHeaders: [],
      clientError: 'Server sent no subprotocol',
    });
  });

  it('refuses a bare-token offer with 401 when the authenticator reads its credential with credentialFromSubprotocol', async () => {
    const {hal, url} = await engine(readsSubprotocol);
    const client = new WebSocket(url, [TOKEN]);

    const clientError = await clientOutcome(client);
    client.close();
    await hal.stop();

    expect(clientError).toBe('Unexpected server response: 401');
  });

  it('writes no offered value to any log line from connect to close, in either shape', async () => {
    await handshake([HAL_WS_SUBPROTOCOL, TOKEN]);
    await refusedHandshake([TOKEN]);

    expect(lines.filter(line => line.includes(TOKEN))).toEqual([]);
  });
});
import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import type {HalServer, HalServerOptions} from './createServer.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
import type {MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import type {SessionStore} from '../types/sessionStore.js';

// Shared by the suites that need a real upgrade over a real socket, which no double can stand in for.

const servers: Array<{stop: () => Promise<void>}> = [];
const clients: WebSocket[] = [];

/** An orchestrator that answers once and stops, which is what commits the turn's assistant entry. */
export const answeringOrchestrator: ChatOrchestrator = {
  processMessage: async () => 'hi',
  async *processMessageStream(): AsyncGenerator<MessageChunk> {
    yield {type: 'text', text: 'hi'};
    yield {type: 'stop', stopReason: 'end_turn'};
  },
};

/** Starts an engine on an ephemeral port and returns the URL a client should open. */
export async function startEngine(
  sessionStore: SessionStore,
  onDisconnect?: (sessionId: string) => void
): Promise<string> {
  const {url} = await startEngineWith({sessionStore, onDisconnect});
  return url;
}

/** Starts an engine with whatever a suite overrides, returning the server itself beside the URL a client should open. */
export async function startEngineWith(
  options: Partial<HalServerOptions> & Pick<HalServerOptions, 'sessionStore'>
): Promise<{url: string; hal: HalServer}> {
  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: 'u1'}),
    orchestrator: answeringOrchestrator,
    ...options,
  });
  await hal.start(0);
  servers.push(hal);
  const {port} = hal.server.address() as AddressInfo;
  return {url: `ws://127.0.0.1:${port}/hal/ws/c1`, hal};
}

/** Opens a client that the suite's teardown will close, whether its test passed or failed. */
export function connectClient(url: string, token = 't'): WebSocket {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, token]);
  clients.push(client);
  return client;
}

/** A promise a test settles by hand, to hold a stream or a hook at a point of its choosing. */
export function deferred(): {until: Promise<void>; release: () => void} {
  let release = (): void => undefined;
  const until = new Promise<void>(resolve => {
    release = resolve;
  });
  return {until, release};
}

/** Resolves with every frame type seen up to and including the first `until` frame. */
export function framesUntil(client: WebSocket, until: string): Promise<string[]> {
  const seen: string[] = [];
  return new Promise<string[]>(resolve => {
    client.on('message', raw => {
      const {type} = JSON.parse(String(raw)) as {type: string};
      seen.push(type);
      if (type === until) resolve(seen);
    });
  });
}

/** Opens a client that asks one question the moment the socket opens, resolving on the first `until` frame. */
export function askOnOpen(
  url: string,
  {until = 'stream_end', token}: {until?: string; token?: string} = {}
): {client: WebSocket; finished: Promise<string[]>} {
  const client = connectClient(url, token);
  const finished = framesUntil(client, until);
  client.on('open', () => client.send(JSON.stringify({type: 'user_message', content: 'hello'})));
  return {client, finished};
}

/** The session id the client's `connected` frame announces, read after the fact; attach it before any frame arrives. */
export function announcedId(client: WebSocket): () => string {
  let sessionId = '';
  client.on('message', raw => {
    const frame = JSON.parse(String(raw)) as {type: string; sessionId?: string};
    if (frame.type === 'connected') sessionId = frame.sessionId ?? '';
  });
  return () => sessionId;
}

/** Tears every socket and server down, so a red test reports instead of hanging the run. */
export async function stopEngines(): Promise<void> {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) await hal.stop();
}

/** The one session a store holds, for asserting what survived a close. */
export async function onlySession(store: SessionStore, sessionId: string): Promise<ChatSession | undefined> {
  return (await store.get(sessionId)) as ChatSession | undefined;
}
